const unsigned int pmic_client_cnt = (unsigned int)(sizeof(pmic_clients) / sizeof(pmic_clients[0]));

const icb_entry_t* lookup_icb_master(unsigned int id)
{
    unsigned int i;
    for (i = 0; i < icb_master_cnt; ++i)
        if (icb_masters[i].id == id)
            return &icb_masters[i];
    return 0;
}

const icb_entry_t* lookup_icb_slave(unsigned int id)
{
    unsigned int i;
    for (i = 0; i < icb_slave_cnt; ++i)
        if (icb_slaves[i].id == id)
            return &icb_slaves[i];
    return 0;
}

const clock_entry_t* lookup_clock(const char* name)
{
    unsigned int i;
    if (!name)
        return 0;
    for (i = 0; i < clock_catalog_cnt; ++i)
        if (same_name(clocks[i].name, name))
            return &clocks[i];
    return 0;
}

int clock_can_reconfigure(const char* name)
{
    const clock_entry_t* c = lookup_clock(name);
    return c && !c->read_only;
}

const rail_entry_t* lookup_rail(const char* name)
{
    unsigned int i;
    if (!name)
        return 0;
    for (i = 0; i < rail_catalog_cnt; ++i)
        if (same_name(rail_catalog[i].name, name))
            return &rail_catalog[i];
    return 0;
}

