const unsigned int icb_route_cnt = (unsigned int)(sizeof(icb_routes) / sizeof(icb_routes[0]));

const icb_route_t* lookup_icb_route(unsigned int master_id, unsigned int slave_id)
{
    unsigned int i;
    for (i = 0; i < icb_route_cnt; ++i)
        if (icb_routes[i].master_id == master_id && icb_routes[i].slave_id == slave_id)
            return &icb_routes[i];
    return 0;
}
